const itemsPath = path.join(__dirname, "..", "content", "source", "items.json");
const gazetteerPath = path.join(__dirname, "..", "content", "source", "gazetteer.json");

const APPROVED_AT = "2026-08-23T00:00:00.000Z";
const NOTES = "Wave 2 (post-'think 1000'): sourced by parallel research agents, centrally re-verified (license + sourceUrl independently re-derived or re-confirmed; spot-checked visually; South Asia/Middle East download+inspection completed centrally after agent rate-limiting) before approval.";

